"""Уроки с воспроизводимыми примерами и ссылками на проверяемые источники.

LESSONS, GLOSSARY и METRIC_HELP — данные публичного каталога API.
Сначала объясняется действие настройки; формулы дополняют численный пример.
"""

from __future__ import annotations

from typing import Any


def _preset(
    model: str,
    *,
    name: str = "linear",
    data: dict[str, Any] | None = None,
    params: dict[str, Any] | None = None,
    epochs: int = 100,
) -> dict[str, Any]:
    dataset_params: dict[str, Any] = {
        "n_samples": 180, "n_features": 2, "noise": 8,
        "correlation": 0.2, "outliers": 0, "seed": 42,
    }
    dataset_params.update(data or {})
    return {
        "dataset": {"kind": "synthetic", "name": name, "params": dataset_params},
        "model": model, "params": dict(params or {}), "epochs": epochs,
    }


def _source(title: str, url: str) -> dict[str, str]:
    return {"title": title, "url": url}


def _sk(name: str, section: str = "linear_model") -> dict[str, str]:
    return _source(
        f"scikit-learn 1.8: {name} — параметры и формула",
        f"https://scikit-learn.org/1.8/modules/generated/sklearn.{section}.{name}.html",
    )


def _guide(title: str, page: str) -> dict[str, str]:
    return _source(title, f"https://scikit-learn.org/1.8/{page}")


_ISLP = _source("Открытый учебник ISLP: главы 3, 5 и 6", "https://www.statlearning.com/")
