_MLWIKI = _source("Конспект ML Wiki: определения (дополнительное чтение)", "https://github.com/alexeygrigorev/mlwiki.org/blob/main/index.php/Linear_Regression.md")
_CV = _guide("scikit-learn: способы перекрестной проверки", "modules/cross_validation.html")
_PREPROC = _guide("scikit-learn: масштабирование и преобразование признаков", "modules/preprocessing.html")
_LEAKAGE = _guide("scikit-learn: утечки данных и типичные ошибки", "common_pitfalls.html")
_PIPELINE = _guide("scikit-learn: Pipeline и ColumnTransformer", "modules/compose.html")
_METRICS = _guide("scikit-learn: метрики регрессии и ограничения", "modules/model_evaluation.html")
_SMOGN = _source("Branco, Torgo, Ribeiro (2017): SMOGN — исходная статья", "https://proceedings.mlr.press/v74/branco17a.html")


def _lesson(
    identifier: str,
    title: str,
    summary: str,
    sections: list[tuple[str, str] | tuple[str, str, str]],
    exercise: str,
    preset: dict[str, Any],
    sources: list[dict[str, str]],
) -> dict[str, Any]:
    return {
        "id": identifier, "title": title, "summary": summary,
        "sections": [
            {"title": part[0], "text": part[1], **({"formula": part[2]} if len(part) == 3 else {})}
            for part in sections
        ],
        "exercise": exercise, "preset": preset, "sources": sources,
    }


