# Небольшой пример в каждой статье помогает проверить смысл термина без формального курса.
# lesson_id ведет к соответствующему учебному разбору в интерфейсе.
GLOSSARY: list[dict[str, str]] = [
    {"term": "Наблюдение · sample", "definition": "Одна строка: одна квартира, один заказ или одно измерение. 200 строк и 5 признаков — разные размеры таблицы.", "lesson_id": "21-read-data"},
    {"term": "Признак · feature", "definition": "Вход модели, известный до прогноза: например, площадь квартиры. Подготовка может создать новые признаки, такие как площадь².", "lesson_id": "01-prediction"},
    {"term": "Целевая переменная · target", "definition": "То, что нужно предсказать: например, цена. Для регрессии это число с содержательным смыслом; код цвета 1/2/3 обычно обозначает категорию.", "lesson_id": "21-read-data"},
    {"term": "Предсказание · prediction", "definition": "Число, которое модель вернула для входов. ŷ = 10 при настоящем y = 11 означает недооценку на 1.", "lesson_id": "01-prediction"},
    {"term": "Коэффициент · coefficient", "definition": "Множитель подготовленного признака. В 3 + 2x коэффициент равен 2: увеличение x на 1 добавляет к прогнозу 2 при неизменных других входах.", "lesson_id": "02-multiple-regression"},
    {"term": "Свободный член · intercept", "definition": "Постоянное число b в прогнозе. В 3 + 2x оно равно 3. Это прогноз для нулевого вектора подготовленных признаков.", "lesson_id": "01-prediction"},
    {"term": "Матрица признаков · design matrix", "definition": "Таблица входов X: строки — наблюдения, столбцы — признаки. После подготовки ее число столбцов может отличаться от исходного.", "lesson_id": "02-multiple-regression"},
    {"term": "Вектор · vector", "definition": "Упорядоченный список чисел. Коэффициенты (2, −3) должны соответствовать тем же двум столбцам в том же порядке.", "lesson_id": "02-multiple-regression"},
    {"term": "Транспонирование · transpose", "definition": "Перестановка строк и столбцов. Таблица 3×2 после операции ᵀ имеет размер 2×3. Используется в формулах линейной алгебры.", "lesson_id": "03-least-squares"},
    {"term": "Остаток · residual", "definition": "Настоящее значение минус прогноз: y − ŷ. Для 11 − 10 остаток +1; плюс означает недооценку.", "lesson_id": "01-prediction"},
    {"term": "Шум · noise", "definition": "Отклонение цели от заданной зависимости. В линейном генераторе noise задает его масштаб в единицах цели; это не процент плохих строк.", "lesson_id": "21-read-data"},
    {"term": "Выброс · outlier", "definition": "Необычная точка относительно выбранной модели данных. Цена 1000 среди обычных цен 5–20 может быть ошибкой или настоящим редким объектом.", "lesson_id": "12-huber"},
    {"term": "Корреляция · correlation", "definition": "Число линейной связи. +1 — точное совместное линейное изменение, −1 — точное противоположное. 0 не исключает кривую зависимость.", "lesson_id": "05-scaling-correlation"},
    {"term": "Мультиколлинеарность · multicollinearity", "definition": "Столбцы линейно повторяют или почти повторяют друг друга. При x₂ = x₁ разные пары коэффициентов с одинаковой суммой дают один прогноз.", "lesson_id": "05-scaling-correlation"},
    {"term": "Функция потерь · loss", "definition": "Цена отдельного промаха или средняя цена. Для ошибки 4 модуль дает 4, квадрат дает 16: разные правила по-разному выделяют крупные ошибки.", "lesson_id": "03-least-squares"},
    {"term": "Полная функция · objective", "definition": "То, что минимизирует обучение: цена ошибок в своей нормировке и добавленный штраф. Между моделями ее числа напрямую не сравнивают.", "lesson_id": "03-least-squares"},
    {"term": "Регуляризация · regularization", "definition": "Предпочтение среди решений: небольшие коэффициенты, меньше признаков, гладкость или ограничения. Может ухудшить обучение ради более устойчивого прогноза.", "lesson_id": "06-ridge"},
    {"term": "Штраф · penalty", "definition": "Дополнительная цена решения. При w = 3 и alpha = 2 Ridge платит 2×3² = 18. Обычная метрика новых прогнозов этот штраф не включает.", "lesson_id": "03-least-squares"},
    {"term": "alpha", "definition": "Сила штрафа у многих моделей. Больше обычно означает сильнее сжатие. Формула зависит от класса: alpha у Ridge, Lasso и BayesianRidge имеет разный смысл.", "lesson_id": "09-paths"},
    {"term": "L₁", "definition": "Сумма модулей коэффициентов. Для (3, −4) равна 7. Такой штраф часто дает точные нули.", "lesson_id": "07-lasso"},
    {"term": "L₂", "definition": "Длина вектора: sqrt(3²+4²) = 5 для (3, 4). Ridge штрафует ее квадрат 25, а не длину 5.", "lesson_id": "06-ridge"},
    {"term": "L₀", "definition": "Число ненулевых коэффициентов. Для (3, 0, −4) равно 2. В строгой математике это не норма, несмотря на историческое название.", "lesson_id": "19-nonconvex"},
    {"term": "Норма · norm", "definition": "Способ измерить размер вектора. Для (3, −4) норма L₁ равна 7, норма L₂ — 5; это разные штрафные величины.", "lesson_id": "06-ridge"},
    {"term": "Разреженность · sparsity", "definition": "Много нулей. Разреженный вектор коэффициентов использует мало столбцов. Разреженный формат хранения таблицы — отдельная вещь.", "lesson_id": "07-lasso"},
    {"term": "l1_ratio", "definition": "Доля компонента L₁ в ElasticNet, от 0 до 1. Значение 0.8 не обещает, что исчезнет 80% признаков.", "lesson_id": "08-elasticnet"},
    {"term": "C · цена ошибок LinearSVR", "definition": "Множитель цены ошибок за пределами полосы epsilon. Большой C ослабляет относительное влияние регуляризации: это направление противоположно alpha у Ridge.", "lesson_id": "31-linear-svr"},
    {"term": "epsilon · полоса LinearSVR", "definition": "Размер промаха без штрафа в единицах цели. При epsilon = 2 ошибка 1 не штрафуется при обучении, но входит в обычную проверочную MAE.", "lesson_id": "31-linear-svr"},
    {"term": "Weighted Lasso", "definition": "Lasso с отдельным весом штрафа каждого подготовленного столбца. При коэффициентах (2, 2) и весах (1, 3) штраф до alpha равен 8.", "lesson_id": "32-weighted-lasso"},
    {"term": "Ранг · rank", "definition": "Число независимых направлений таблицы. Два одинаковых столбца добавляют одно направление. Недостаток ранга делает коэффициенты МНК неоднозначными.", "lesson_id": "05-scaling-correlation"},
    {"term": "Псевдообратная матрица · pseudoinverse", "definition": "Обобщение обратной матрицы, позволяющее решать МНК и для прямоугольных или зависимых столбцов. Из нескольких решений выбирает решение наименьшей L₂-нормы.", "lesson_id": "03-least-squares"},
    {"term": "Среднее · mean", "definition": "Сумма, деленная на количество. Для 1, 2 и 12 это 5. Крайнее число 12 заметно сдвинуло среднее.", "lesson_id": "22-missing-values"},
    {"term": "Медиана · median", "definition": "Центр отсортированных чисел. Для 1, 2 и 12 это 2; для 1, 2, 3, 12 обычно берут (2+3)/2 = 2.5.", "lesson_id": "22-missing-values"},
    {"term": "Стандартное отклонение · standard deviation", "definition": "Мера разброса вокруг среднего в тех же единицах. Если среднее 100 и масштаб 20, значение 140 на два масштаба выше среднего.", "lesson_id": "05-scaling-correlation"},
    {"term": "Стандартизация · standardization", "definition": "Вычесть обучающее среднее и разделить на обучающее стандартное отклонение. При 100 и 20 значение 140 превращается в 2. Это не делает любое распределение нормальным.", "lesson_id": "05-scaling-correlation"},
    {"term": "RobustScaler", "definition": "Масштабирует по медиане и межквартильному диапазону. Эти величины слабее реагируют на крайние значения; выбросы при этом не удаляются.", "lesson_id": "24-feature-engineering"},
    {"term": "MinMaxScaler", "definition": "Переводит обучающий минимум и максимум в заданные границы, обычно 0 и 1. Новое число за обучающим диапазоном может выйти за эти границы.", "lesson_id": "24-feature-engineering"},
    {"term": "MaxAbsScaler", "definition": "Делит столбец на максимальный обучающий модуль, сохраняя ноль и знак. При максимальном модуле 10 значение −5 становится −0.5.", "lesson_id": "24-feature-engineering"},
    {"term": "Заполнение пропусков · imputation", "definition": "Замена пустой ячейки по заданному правилу. Медиана считается на обучении, затем то же число применяется к другим строкам.", "lesson_id": "22-missing-values"},
    {"term": "Индикатор пропуска · missing indicator", "definition": "Дополнительный столбец 1/0, показывающий, была ли ячейка пустой до заполнения. Он различает настоящий ноль и заполненный ноль.", "lesson_id": "22-missing-values"},
    {"term": "KNNImputer", "definition": "Заполняет по строкам с похожими известными входами. Расстояния зависят от единиц; соседство и качество стоит проверять отдельно.", "lesson_id": "22-missing-values"},
    {"term": "Индикаторное кодирование · one-hot", "definition": "Каждому названию создается столбец 1/0. Для трех цветов синий представлен (0, 0, 1); искусственного числового порядка нет.", "lesson_id": "23-categories"},
    {"term": "Полиномиальные признаки · polynomial features", "definition": "Столбцы со степенями и произведениями: x² или x₁x₂. Кривая может оставаться линейной по обучаемым коэффициентам.", "lesson_id": "24-feature-engineering"},
    {"term": "Взаимодействие · interaction", "definition": "Произведение разных входов. x₁x₂ позволяет вкладу первого признака зависеть от второго; для 3 и 4 получается 12.", "lesson_id": "24-feature-engineering"},
    {"term": "Обрезка крайних значений · clipping", "definition": "Замена значений за границами на границы. При диапазоне 0…100 число 500 становится 100. Квантильные границы учатся на train; смысл крайних событий надо сохранить.", "lesson_id": "24-feature-engineering"},
    {"term": "Отбор признаков · feature selection", "definition": "Выбор части столбцов, например по связи с обучающей целью. Если выбирать по всем y до проверки, получится утечка.", "lesson_id": "25-data-leakage"},
    {"term": "Гиперпараметр · hyperparameter", "definition": "Настройка до обучения: alpha, степень, шаг. Коэффициент w, который обучение подбирает само, — параметр модели.", "lesson_id": "27-hyperparameter-search"},
    {"term": "Базовое сравнение · baseline", "definition": "Простой прогноз для оценки пользы модели. Например, постоянное среднее обучающей цели. Если сложная модель хуже него на новых строках, объясни зачем она нужна.", "lesson_id": "20-metrics-experiment"},
    {"term": "Градиент · gradient", "definition": "Как меняется функция при малых изменениях параметров. Для уменьшения функции делают небольшой шаг в обратную сторону.", "lesson_id": "10-sgd"},
    {"term": "Скорость обучения · learning rate", "definition": "Размер обновления eta. Увеличение с 0.001 до 0.1 делает тот же градиентный шаг в 100 раз больше и может вызвать расходимость.", "lesson_id": "10-sgd"},
    {"term": "eta0", "definition": "Начальный размер шага у SGD. В режиме constant он остается постоянным; другие расписания меняют шаг с обучением.", "lesson_id": "10-sgd"},
    {"term": "Эпоха · epoch", "definition": "Один проход по всем обучающим строкам. В 100 строках и 10 эпохах было 10 полных проходов; это не 10 новых независимых датасетов.", "lesson_id": "10-sgd"},
    {"term": "Сходимость · convergence", "definition": "Численный алгоритм достиг своего условия остановки. Это говорит о решении задачи, но не о качестве на новых данных.", "lesson_id": "09-paths"},
    {"term": "tol", "definition": "Допуск критерия остановки. У разных решателей условия разные. tol = 0.001 не означает ошибку прогноза меньше 0.001 рубля.", "lesson_id": "09-paths"},
    {"term": "max_iter", "definition": "Лимит итераций решателя. Малый лимит может оборвать оптимизацию; большой лишь разрешает дольше считать, а не гарантирует лучшее обобщение.", "lesson_id": "09-paths"},
    {"term": "Путь регуляризации · regularization path", "definition": "Решения при нескольких alpha на одинаковом обучении. Каждая точка — другая сила штрафа, а не следующая эпоха одной задачи.", "lesson_id": "09-paths"},
    {"term": "Активный набор · active set", "definition": "Столбцы, участвующие в текущем этапе. OMP добавляет их жадно; LassoLars может также исключать столбец после обнуления.", "lesson_id": "11-lars-omp"},
    {"term": "Выпуклость · convexity", "definition": "У выпуклой задачи локальный минимум является глобальным. Несколько разных коэффициентов все еще могут давать одинаковое минимальное значение.", "lesson_id": "03-least-squares"},
    {"term": "Локальный минимум · local minimum", "definition": "Результат лучше соседних вариантов, но далеко может быть еще лучше. У невыпуклых штрафов старт и решатель могут влиять на итог.", "lesson_id": "19-nonconvex"},
    {"term": "Устойчивость · robustness", "definition": "Слабая чувствительность к конкретному загрязнению. Huber ослабляет большие остатки, но не дает полной защиты от любого экстремального входа.", "lesson_id": "12-huber"},
    {"term": "Гетероскедастичность · heteroscedasticity", "definition": "Разброс ошибок зависит от входа. На графике остатков получается веер: для дорогих объектов промахи шире, чем для дешевых.", "lesson_id": "15-quantile"},
    {"term": "Обучение · train", "definition": "Строки для подгонки модели и статистик подготовки. При 60/20/20 из 200 строк их 120.", "lesson_id": "04-generalization"},
    {"term": "Проверка · validation", "definition": "Строки для сравнения вариантов и подбора. После 100 подборов по ним это часть разработки, а не нетронутый итоговый тест.", "lesson_id": "04-generalization"},
    {"term": "Итоговый тест · test", "definition": "Отложенные строки для уже выбранного варианта. Если после просмотра теста менять настройки, нужен новый независимый итоговый набор.", "lesson_id": "04-generalization"},
    {"term": "Перекрестная проверка · cross-validation", "definition": "Несколько внутренних разбиений обучения. В пяти сгибах каждый участок по очереди оценивается моделью, обученной на остальных.", "lesson_id": "26-cross-validation"},
    {"term": "Сгиб · fold", "definition": "Одна часть в перекрестной проверке. В KFold из 100 строк с 5 сгибами каждый содержит 20 строк.", "lesson_id": "26-cross-validation"},
    {"term": "Групповая проверка · GroupKFold", "definition": "Строки одного клиента или устройства остаются в одной группе. Модель проверяется на группах, которых не было в соответствующем обучении.", "lesson_id": "26-cross-validation"},
    {"term": "Временная проверка · TimeSeriesSplit", "definition": "Обучение на более ранних строках, оценка на следующих. Требует правильной сортировки и учета того, что реально известно на дату прогноза.", "lesson_id": "26-cross-validation"},
    {"term": "Вложенная проверка · nested CV", "definition": "Внутренние сгибы подбирают настройки, внешние оценивают всю процедуру. Итоговая внешняя оценка не участвует в выборе внутренних победителей.", "lesson_id": "26-cross-validation"},
    {"term": "Утечка данных · data leakage", "definition": "Использование сведений, которых еще не будет при реальном прогнозе. Пример: дата оплаты для прогноза оплаты или отбор столбца по тестовым целям.", "lesson_id": "25-data-leakage"},
    {"term": "Случайное зерно · random seed", "definition": "Число для повторения псевдослучайных действий. Одинаковое зерно повторяет опыт; качество на других зернах надо исследовать отдельно.", "lesson_id": "04-generalization"},
    {"term": "Pipeline", "definition": "Сохраненная цепочка: заполнение, преобразования, модель. На обучении она подбирает статистики, на прогнозе повторяет подготовку с ними.", "lesson_id": "25-data-leakage"},
    {"term": "Сетка · grid search", "definition": "Перебор всех заданных сочетаний. Пять alpha и три доли L₁ дают 15 моделей до учета сгибов.", "lesson_id": "27-hyperparameter-search"},
    {"term": "Случайный поиск · random search", "definition": "Заданное число случайных сочетаний из пространства настроек. Бюджет 20 проверяет 20 вариантов, а не все возможные.", "lesson_id": "27-hyperparameter-search"},
    {"term": "Optuna · trial", "definition": "Optuna организует подбор; trial — одна попытка с набором настроек и оценкой. Лучший trial — лучший среди выполненных, без гарантии глобального оптимума.", "lesson_id": "27-hyperparameter-search"},
    {"term": "TPE", "definition": "Алгоритм Optuna, предлагающий настройки по результатам прежних попыток. Нужны корректная метрика, направление и разумные диапазоны.", "lesson_id": "27-hyperparameter-search"},
    {"term": "Отсечение попыток · pruning", "definition": "Раннее прекращение неудачной попытки по промежуточным оценкам. Возможно только когда эти оценки действительно доступны.", "lesson_id": "27-hyperparameter-search"},
    {"term": "Oversampling", "definition": "Увеличение числа обучающих примеров выбранной области: копированием или синтезом. Само по себе не добавляет независимых измерений.", "lesson_id": "28-rare-target-smoter"},
    {"term": "Undersampling", "definition": "Уменьшение числа обычных обучающих строк. Меняет внимание модели и экономит время, но удаляет часть доступной информации.", "lesson_id": "28-rare-target-smoter"},
    {"term": "SMOTER", "definition": "Синтетические примеры для редкой важной области непрерывной цели. Использует соседей и правила расчета новой цели; обычный классификационный SMOTE — другая постановка.", "lesson_id": "28-rare-target-smoter"},
    {"term": "SMOGN", "definition": "Метод для регрессии, сочетающий интерполяцию, шум и возможное уменьшение обычной области. Итоговое число строк может уменьшиться.", "lesson_id": "28-rare-target-smoter"},
    {"term": "Relevance · важность значения цели", "definition": "Функция от y со значением 0…1. Порог выделяет нужные редкие области; это не важность признака и не классификационная метка.", "lesson_id": "28-rare-target-smoter"},
    {"term": "Априорное распределение · prior", "definition": "Предположение о коэффициентах до текущих данных. Например, значения около нуля считаются вероятнее очень больших.", "lesson_id": "14-bayesian"},
    {"term": "Апостериорное распределение · posterior", "definition": "Вероятностное описание коэффициентов после учета данных в выбранной модели.", "lesson_id": "14-bayesian"},
    {"term": "Точность распределения · precision", "definition": "В байесовских моделях это 1/дисперсия. Если дисперсия 4, точность 0.25. Метрика precision классификации имеет другой смысл.", "lesson_id": "14-bayesian"},
    {"term": "Квантиль · quantile", "definition": "Граница для доли распределения. 0.5 — медиана, 0.9 — верхняя граница примерно для 90% значений при подходящей модели.", "lesson_id": "15-quantile"},
    {"term": "Функция связи · link function", "definition": "Соединяет среднее цели с линейным расчетом GLM. При log-связи log(mu) = b + Xw, поэтому возвращаемый mu положителен.", "lesson_id": "16-glm"},
    {"term": "Девианса · deviance", "definition": "Цена расхождения факта и прогноза для выбранного семейства распределений. Poisson и Gamma имеют разные формулы и ограничения по знаку.", "lesson_id": "16-glm"},
    {"term": "Срез · slice", "definition": "График выбранных входов при фиксированных остальных. В модели с пятью признаками 3D показывает один такой срез, а не весь объект.", "lesson_id": "02-multiple-regression"},
    {"term": "Экстраполяция · extrapolation", "definition": "Прогноз вне обучавшего диапазона. Прямая по квартирам 30–100 м² может плохо предсказывать дворец 1000 м².", "lesson_id": "30-interpretation"},
    {"term": "Перестановочная важность · permutation importance", "definition": "Изменение метрики после перемешивания одного столбца у готовой модели. MAE 5 → 12 означает ухудшение на 7, но не доказывает причинность.", "lesson_id": "30-interpretation"},
    {"term": "Joblib", "definition": "Python-формат сохранения подготовленной модели и цепочки. Требует совместимой среды; неизвестный файл может выполнять код при загрузке.", "lesson_id": "29-model-export"},
    {"term": "ONNX", "definition": "Формат вычислительного графа для запуска прогноза в другой среде. Конвертер должен поддерживать каждое преобразование и модель выбранной цепочки.", "lesson_id": "29-model-export"},
]


METRIC_HELP: dict[str, str] = {
    "mse": "MSE — средний квадрат промаха. Для ошибок 1, −1, 4: (1+1+16)/3 = 6. Меньше лучше. Единицы цели в квадрате: если y в рублях, MSE в рублях². Большие промахи особенно дороги.",
    "rmse": "RMSE — корень из MSE. Для ошибок 1, −1, 4 примерно 2.45. Меньше лучше; те же единицы, что у цели. Сильнее реагирует на крупные промахи, чем MAE. Не означает, что каждый прогноз ошибается на это число.",
    "mae": "MAE — средний модуль промаха. Для ошибок 1, −1, 4: (1+1+4)/3 = 2. Меньше лучше. MAE = 5 рублей означает средний абсолютный промах 5 рублей, без информации о его направлении.",
    "median_ae": "Медианная абсолютная ошибка — середина отсортированных модулей промаха. Для ошибок 1, 2, 100 равна 2. Меньше лучше. Описывает центральную ошибку и может скрыть небольшую долю очень крупных промахов.",
    "max_error": "Максимальный модуль промаха. Для ошибок 1, −2, 100 равен 100. Меньше лучше. Описывает худшую наблюденную ошибку; на другом или более крупном наборе максимум может быть другим.",
    "r2": "R² сравнивает SSE модели с SSE постоянного среднего оцениваемой цели. Если они 20 и 100, R² = 1−20/100 = 0.8. Больше лучше; 1 — идеально, 0 — равные SSE, отрицательное — модель хуже. Это не 80% правильных ответов. При постоянной цели обычная формула не определена.",
    "explained_variance": "Объясненная дисперсия сравнивает разброс остатков с разбросом цели. Больше лучше. Если каждый прогноз завышен ровно на 10, остатки постоянны и показатель может быть 1, хотя ошибка велика. Смотри также MAE и R².",
    "mape": "MAPE — средний модуль ошибки относительно настоящего y. Промах 10 при y = 100 дает 0.1, то есть 10%; библиотека возвращает долю. Меньше лучше. При y около нуля даже небольшой промах дает огромное число; для нулевых и знакопеременных целей выбери подходящий другой критерий.",
    "smape": "sMAPE в лаборатории: 200×mean(|y−pred|/(|y|+|pred|)). Для y = 100 и pred = 80 это примерно 22.22%. Меньше лучше; шкала 0…200%. При y = pred = 0 вклад принят равным нулю. В других инструментах встречаются иные соглашения о множителе.",
    "msle": "MSLE сравнивает log(1+y) и log(1+pred), затем усредняет квадраты разностей. Меньше лучше. Оба числа должны быть неотрицательными. Ценит соотношение размеров иначе, чем обычный MSE; результат не в единицах цены или времени.",
    "rmsle": "RMSLE — корень из MSLE. Меньше лучше. Настоящие значения и прогнозы должны быть неотрицательными. Логарифмическая ошибка не переводится напрямую в средний промах в рублях.",
    "pinball": "Квантильная потеря: при q = 0.9 недооценка на 10 стоит 9, переоценка на 10 — 1. Меньше лучше. Установи q той квантильной модели, которую оцениваешь. При q = 0.5 метрика равна половине MAE.",
    "poisson_deviance": "Poisson-девианса — цена расхождения с положительным средним модели Poisson. Меньше лучше. Нужны y ≥ 0 и pred > 0; настоящий ноль допустим. Для счетчиков полезно смотреть вместе с MAE в штуках.",
    "gamma_deviance": "Gamma-девианса — цена относительного расхождения положительных величин. Меньше лучше. Нужны строго положительные y и pred: нулевой факт или отрицательный прогноз делают метрику недопустимой.",
    "tweedie_deviance": "Tweedie-девианса зависит от power. Меньше лучше. При 0 совпадает с MSE и допускает любой знак; при 1 нужна неотрицательная цель и положительный прогноз; от 1 до 2 нули цели допустимы; при ≥2 оба строго положительны. Диапазон 0<power<1 недопустим. Не сравнивай разные power как одну шкалу.",
    "custom": "Своя формула получает y, pred и error = y−pred. sqrt(mean(error**2)) повторяет RMSE. mean(abs(error)+clip(error,0,1e12)) делает недооценку до границы вдвое дороже переоценки. Нужен один конечный результат и явно выбранное направление: минимум или максимум.",
}

for _alias, _canonical in {
    "medae": "median_ae", "median_absolute_error": "median_ae", "max_ae": "max_error",
    "evs": "explained_variance", "ev": "explained_variance",
    "pinball_loss": "pinball", "mean_pinball_loss": "pinball",
    "poisson": "poisson_deviance", "gamma": "gamma_deviance",
    "mean_poisson_deviance": "poisson_deviance", "mean_gamma_deviance": "gamma_deviance",
}.items():
    METRIC_HELP[_alias] = METRIC_HELP[_canonical]
